// Package argparse is a minimal command-line argument parser.
package argparse

import (
	"errors"
	"fmt"
	"strconv"
	"strings"
	"text/tabwriter"
)

// ErrHelp is returned by Parse when -h or --help is given and not defined as a flag.
var ErrHelp = errors.New("help requested")

type flagDef struct {
	name, usage, def string
	isBool           bool
	set              func(string) error
}

// Parser holds the flag definitions for one command.
type Parser struct {
	name  string
	flags []*flagDef
}

// New returns a parser for the named program.
func New(name string) *Parser { return &Parser{name: name} }

func (p *Parser) lookup(name string) *flagDef {
	for _, f := range p.flags {
		if f.name == name {
			return f
		}
	}
	return nil
}

func (p *Parser) add(f *flagDef) {
	if f.name == "" || f.name[0] == '-' || strings.Contains(f.name, "=") {
		panic("argparse: invalid flag name " + strconv.Quote(f.name))
	}
	if p.lookup(f.name) != nil {
		panic("argparse: flag redefined: " + f.name)
	}
	p.flags = append(p.flags, f)
}

// Bool defines a boolean flag: -name, -name=true, -name=false.
func (p *Parser) Bool(name, usage string) *bool {
	v := new(bool)
	p.add(&flagDef{name: name, usage: usage, isBool: true, set: func(s string) error {
		b, err := strconv.ParseBool(s)
		if err == nil {
			*v = b
		}
		return err
	}})
	return v
}

// String defines a string flag: -name value or -name=value.
func (p *Parser) String(name, def, usage string) *string {
	v := &def
	f := &flagDef{name: name, usage: usage, set: func(s string) error {
		*v = s
		return nil
	}}
	if def != "" {
		f.def = strconv.Quote(def)
	}
	p.add(f)
	return v
}

// Int defines an integer flag: -name value or -name=value.
func (p *Parser) Int(name string, def int, usage string) *int {
	v := &def
	p.add(&flagDef{name: name, usage: usage, def: strconv.Itoa(def), set: func(s string) error {
		n, err := strconv.Atoi(s)
		if err == nil {
			*v = n
		}
		return err
	}})
	return v
}

// Parse reads args (typically os.Args[1:]) and returns the positional
// arguments. Flags may use one or two dashes and may appear anywhere;
// everything after a bare "--" is positional.
func (p *Parser) Parse(args []string) ([]string, error) {
	var pos []string
	for i := 0; i < len(args); i++ {
		a := args[i]
		if a == "--" {
			return append(pos, args[i+1:]...), nil
		}
		if len(a) < 2 || a[0] != '-' {
			pos = append(pos, a)
			continue
		}
		name, val, hasVal := strings.Cut(strings.TrimPrefix(a[1:], "-"), "=")
		f := p.lookup(name)
		switch {
		case f == nil && (name == "h" || name == "help"):
			return nil, ErrHelp
		case f == nil:
			return nil, fmt.Errorf("unknown flag: %s", a)
		case f.isBool && !hasVal:
			val = "true"
		case !hasVal:
			if i++; i == len(args) {
				return nil, fmt.Errorf("flag needs a value: %s", a)
			}
			val = args[i]
		}
		if err := f.set(val); err != nil {
			return nil, fmt.Errorf("invalid value %q for flag --%s: %w", val, name, err)
		}
	}
	return pos, nil
}

// Usage returns a help message generated from the flag definitions.
func (p *Parser) Usage() string {
	var b strings.Builder
	fmt.Fprintf(&b, "Usage: %s [flags] [args...]\n\nFlags:\n", p.name)
	w := tabwriter.NewWriter(&b, 0, 0, 2, ' ', 0)
	for _, f := range p.flags {
		left, right := "--"+f.name, f.usage
		if !f.isBool {
			left += " value"
		}
		if f.def != "" {
			right += " (default " + f.def + ")"
		}
		fmt.Fprintf(w, "  %s\t%s\n", left, right)
	}
	fmt.Fprintf(w, "  --help\tshow this help\n")
	w.Flush()
	return b.String()
}
EOF
