		if _, err := p.Parse(bad); err == nil || errors.Is(err, ErrHelp) {
			t.Errorf("Parse(%q) err = %v, want parse error", bad, err)
		}
	}
	if _, err := p.Parse([]string{"-h"}); !errors.Is(err, ErrHelp) {
		t.Errorf("-h err = %v, want ErrHelp", err)
	}

