Flags:
  --verbose    print more
  --quiet      print less
  --out value  output file (default "a.txt")
  --n value    repeat count (default 1)
  --help       show this help
`
	if got := p.Usage(); got != want {
		t.Errorf("Usage:\n%s\nwant:\n%s", got, want)
	}
}
